package io.github.hienpham0344.stayfinder.user;
import io.github.hienpham0344.stayfinder.user.service.UserPreferencesService;import io.github.hienpham0344.stayfinder.user.repository.*;import io.github.hienpham0344.stayfinder.user.entity.*;import io.github.hienpham0344.stayfinder.user.dto.*;import io.github.hienpham0344.stayfinder.common.exception.*;
import jakarta.persistence.EntityManager;import org.junit.jupiter.api.Test;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class UserPreferencesTest{
 @Test void defaultsAndPatchAreOwnedAndLimited(){var rows=mock(UserPreferencesRepository.class);var users=mock(UserRepository.class);var service=new UserPreferencesService(rows,users,mock(EntityManager.class));var owner=UUID.randomUUID();var other=UUID.randomUUID();when(users.lockById(owner)).thenReturn(Optional.of(new User()));assertEquals("en-US",service.get(owner).language());assertTrue(service.get(owner).bookingNotifications());var stored=new java.util.HashMap<UUID,UserPreferences>();when(rows.findById(any())).thenAnswer(i->Optional.ofNullable(stored.get(i.getArgument(0))));when(rows.save(any())).thenAnswer(i->{UserPreferences value=i.getArgument(0);stored.put(value.getUserId(),value);return value;});var result=service.patch(owner,new PreferencesRequest("vi-VN",false));assertEquals("vi-VN",result.language());assertFalse(result.bookingNotifications());assertEquals("vi-VN",service.get(owner).language());assertEquals("en-US",service.get(other).language());assertTrue(service.get(other).bookingNotifications());}
 @Test void rejectsUnknownLanguageAndEmptyPatch(){var rows=mock(UserPreferencesRepository.class);var service=new UserPreferencesService(rows,mock(UserRepository.class),mock(EntityManager.class));assertThrows(BusinessException.class,()->service.patch(UUID.randomUUID(),new PreferencesRequest("unknown",true)));assertThrows(BusinessException.class,()->service.patch(UUID.randomUUID(),new PreferencesRequest(null,null)));verify(rows,never()).save(any());}
}
